ALTER TABLE public.supervisor_rosters DROP CONSTRAINT supervisor_rosters_rotation_days_check;
ALTER TABLE public.supervisor_rosters ADD CONSTRAINT supervisor_rosters_rotation_days_check CHECK (rotation_days BETWEEN 1 AND 365);
CREATE OR REPLACE FUNCTION public.save_standby_track(_track text,_start date,_rotation_days int,_per_shift int,_order uuid[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c uuid=public.current_company_id(); BEGIN
IF c IS NULL OR NOT public.member_is_active(auth.uid()) OR NOT public.is_company_manager() OR NOT public.company_module_access(c,'standby') THEN RAISE EXCEPTION 'On-call manager access required' USING ERRCODE='42501';END IF;
IF _track IS NULL OR _track NOT IN ('technician','supervisor') OR _start IS NULL OR _rotation_days IS NULL OR _rotation_days NOT BETWEEN 1 AND 365 OR _order IS NULL OR _per_shift IS NULL OR _per_shift<1 OR (_per_shift>cardinality(_order) AND cardinality(_order)>0) OR (cardinality(_order)=0 AND _per_shift<>1) OR cardinality(_order)<>(SELECT count(DISTINCT x) FROM unnest(_order) x) THEN RAISE EXCEPTION 'Invalid roster settings';END IF;
IF EXISTS(SELECT 1 FROM unnest(_order) x WHERE NOT EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=x AND r.company_id=c AND r.role::text=_track AND public.member_is_active(x))) THEN RAISE EXCEPTION 'Choose active members of the same rota role';END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(c::text||':standby',0));
IF _track='technician' THEN UPDATE public.company_settings SET standby_start=_start,standby_rotation_days=_rotation_days,standby_per_shift=_per_shift,standby_order=_order WHERE company_id=c;IF NOT FOUND THEN RAISE EXCEPTION 'Company settings must be initialized by an office admin';END IF;
ELSE INSERT INTO public.supervisor_rosters(company_id,start_date,rotation_days,per_shift,member_order,updated_by) VALUES(c,_start,_rotation_days,_per_shift,_order,auth.uid()) ON CONFLICT(company_id) DO UPDATE SET start_date=excluded.start_date,rotation_days=excluded.rotation_days,per_shift=excluded.per_shift,member_order=excluded.member_order,updated_by=auth.uid(),updated_at=now();END IF;
INSERT INTO public.standby_roster_audit(company_id,track,config,changed_by) VALUES(c,_track,jsonb_build_object('start',_start,'rotationDays',_rotation_days,'perShift',_per_shift,'order',_order),auth.uid()); END $$;
ALTER TABLE public.member_access_events ADD COLUMN handover jsonb;
CREATE FUNCTION public.member_handover_preview(_user uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE c uuid=public.current_company_id(); t public.user_roles; BEGIN
SELECT * INTO t FROM public.user_roles WHERE user_id=_user AND company_id=c;
IF NOT public.has_company_role('admin') OR t.user_id IS NULL OR _user=auth.uid() OR t.platform_owner OR (t.role='superuser' AND public.my_role()<>'superuser') THEN RAISE EXCEPTION 'You cannot manage this member' USING ERRCODE='42501'; END IF;
RETURN jsonb_build_object('jobs',coalesce((SELECT jsonb_agg(jsonb_build_object('id',j.id,'number',j.job_number,'date',j.scheduled_date,'summary',j.problem_summary,'slot',CASE WHEN j.assigned_technician_id=_user THEN 'lead' WHEN j.secondary_technician_id=_user THEN 'assistant' ELSE 'crew' END) ORDER BY j.scheduled_date,j.job_number) FROM public.jobs j WHERE j.company_id=c AND j.scheduled_date>=current_date AND (j.assigned_technician_id=_user OR j.secondary_technician_id=_user OR EXISTS(SELECT 1 FROM public.job_crew x WHERE x.job_id=j.id AND x.user_id=_user)) AND NOT EXISTS(SELECT 1 FROM public.job_sheets s WHERE s.job_id=j.id AND s.status='completed')),'[]'::jsonb),'openShifts',(SELECT count(*) FROM public.shifts WHERE company_id=c AND user_id=_user AND ended_at IS NULL),'tracks',to_jsonb(array_remove(ARRAY[CASE WHEN EXISTS(SELECT 1 FROM public.company_settings WHERE company_id=c AND _user=ANY(standby_order)) THEN 'technician' END,CASE WHEN EXISTS(SELECT 1 FROM public.supervisor_rosters WHERE company_id=c AND _user=ANY(member_order)) THEN 'supervisor' END],NULL)),'swaps',(SELECT count(*) FROM public.standby_swaps WHERE company_id=c AND (requester_id=_user OR target_id=_user) AND coalesce(end_date,swap_date)>=current_date AND status IN('pending','accepted')));
END $$;
REVOKE ALL ON FUNCTION public.member_handover_preview(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.member_handover_preview(uuid) TO authenticated;
CREATE FUNCTION public.terminate_member_handover(_user uuid,_reason text,_choices jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c uuid=public.current_company_id(); t public.user_roles; j public.jobs; choice jsonb; replacement uuid; detail jsonb='[]'; closed jsonb; tracks jsonb='[]'; cfg record; o uuid[]; per int; swapped int; BEGIN
SELECT * INTO t FROM public.user_roles WHERE user_id=_user AND company_id=c FOR UPDATE;
IF NOT public.has_company_role('admin') OR t.user_id IS NULL OR _user=auth.uid() OR t.platform_owner OR (t.role='superuser' AND public.my_role()<>'superuser') THEN RAISE EXCEPTION 'You cannot manage this member' USING ERRCODE='42501'; END IF;
IF t.registration_status<>'active' THEN RAISE EXCEPTION 'Member is already terminated'; END IF;
IF nullif(trim(_reason),'') IS NULL OR _choices IS NULL OR jsonb_typeof(_choices)<>'array' THEN RAISE EXCEPTION 'Enter a reason and review the handover'; END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(c::text||':standby',0));
FOR j IN SELECT * FROM public.jobs WHERE company_id=c AND scheduled_date>=current_date AND (assigned_technician_id=_user OR secondary_technician_id=_user OR EXISTS(SELECT 1 FROM public.job_crew x WHERE x.job_id=jobs.id AND x.user_id=_user)) AND NOT EXISTS(SELECT 1 FROM public.job_sheets s WHERE s.job_id=jobs.id AND s.status='completed') ORDER BY id FOR UPDATE LOOP
SELECT value INTO choice FROM jsonb_array_elements(_choices) WHERE value->>'jobId'=j.id::text;
IF choice IS NULL THEN RAISE EXCEPTION 'Scheduled work changed. Reload and review every assignment'; END IF;
replacement=nullif(choice->>'replacement','')::uuid;
IF replacement IS NOT NULL THEN
PERFORM 1 FROM public.user_roles WHERE user_id=replacement AND company_id=c AND registration_status='active' AND role IN('technician','supervisor','maintenance') FOR UPDATE;
IF NOT FOUND OR replacement=_user OR replacement IN(j.assigned_technician_id,j.secondary_technician_id) OR EXISTS(SELECT 1 FROM public.job_crew WHERE job_id=j.id AND user_id=replacement) THEN RAISE EXCEPTION 'Choose another active field staff member'; END IF;
IF EXISTS(SELECT 1 FROM public.leave_requests WHERE company_id=c AND user_id=replacement AND status='approved' AND j.scheduled_date BETWEEN start_date AND end_date) THEN RAISE EXCEPTION 'Replacement is on approved leave'; END IF;
END IF;
detail=detail||jsonb_build_array(jsonb_build_object('job',j.id,'beforeLead',j.assigned_technician_id,'beforeAssistant',j.secondary_technician_id,'replacement',replacement));
IF j.assigned_technician_id=_user THEN
UPDATE public.jobs SET assigned_technician_id=coalesce(replacement,secondary_technician_id),secondary_technician_id=CASE WHEN replacement IS NULL THEN NULL ELSE secondary_technician_id END,acknowledged_at=NULL,handover_note=left('Termination handover: '||_reason,2000),handover_action=CASE WHEN replacement IS NULL THEN 'office_dispatch' ELSE 'reassigned' END,handover_at=now() WHERE id=j.id AND company_id=c;
ELSIF j.secondary_technician_id=_user THEN UPDATE public.jobs SET secondary_technician_id=replacement,handover_note=left('Termination handover: '||_reason,2000),handover_action=CASE WHEN replacement IS NULL THEN 'office_dispatch' ELSE 'reassigned' END,handover_at=now() WHERE id=j.id AND company_id=c;
ELSE DELETE FROM public.job_crew WHERE job_id=j.id AND user_id=_user AND company_id=c; IF replacement IS NOT NULL THEN INSERT INTO public.job_crew(job_id,user_id,company_id,added_by) VALUES(j.id,replacement,c,auth.uid()); END IF; UPDATE public.jobs SET handover_note=left('Termination handover: '||_reason,2000),handover_action=CASE WHEN replacement IS NULL THEN 'office_dispatch' ELSE 'reassigned' END,handover_at=now() WHERE id=j.id AND company_id=c; END IF;
END LOOP;
FOR cfg IN SELECT 'technician'::text track,standby_start st,standby_rotation_days rot,standby_per_shift staffing,standby_order members FROM public.company_settings WHERE company_id=c AND _user=ANY(standby_order) UNION ALL SELECT 'supervisor',start_date,rotation_days,per_shift,member_order FROM public.supervisor_rosters WHERE company_id=c AND _user=ANY(member_order) LOOP
o=array_remove(cfg.members,_user); per=greatest(1,least(cfg.staffing,cardinality(o)));
IF cfg.track='technician' THEN UPDATE public.company_settings SET standby_order=o,standby_per_shift=per WHERE company_id=c; ELSE UPDATE public.supervisor_rosters SET member_order=o,per_shift=per,updated_by=auth.uid(),updated_at=now() WHERE company_id=c; END IF;
tracks=tracks||jsonb_build_array(cfg.track); INSERT INTO public.standby_roster_audit(company_id,track,config,changed_by) VALUES(c,cfg.track,jsonb_build_object('start',cfg.st,'rotationDays',cfg.rot,'perShift',per,'order',o,'removed',_user,'reason','termination'),auth.uid());
END LOOP;
WITH updated AS (UPDATE public.shifts SET ended_at=greatest(started_at,now()),auto_closed=true,auto_close_note=left('Closed by office on termination: '||_reason,2000) WHERE company_id=c AND user_id=_user AND ended_at IS NULL RETURNING id,started_at,ended_at) SELECT coalesce(jsonb_agg(to_jsonb(updated)),'[]') INTO closed FROM updated;
SELECT count(*) INTO swapped FROM public.standby_swaps WHERE company_id=c AND (requester_id=_user OR target_id=_user) AND coalesce(end_date,swap_date)>=current_date AND status IN('pending','accepted');
PERFORM public.set_member_access(_user,false,_reason);
UPDATE public.member_access_events SET handover=jsonb_build_object('jobs',detail,'closedShifts',closed,'removedTracks',tracks,'unavailableSwaps',swapped) WHERE id=(SELECT id FROM public.member_access_events WHERE company_id=c AND user_id=_user AND actor_id=auth.uid() AND action='terminated' ORDER BY created_at DESC LIMIT 1);
END $$;
REVOKE ALL ON FUNCTION public.terminate_member_handover(uuid,text,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.terminate_member_handover(uuid,text,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.is_on_standby(_user uuid,_date date) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE c uuid; BEGIN SELECT company_id INTO c FROM public.users WHERE id=_user; IF c IS NULL OR c IS DISTINCT FROM public.current_company_id() OR NOT public.member_is_active(auth.uid()) OR NOT public.member_is_active(_user) OR NOT public.company_module_access(c,'standby') THEN RETURN false;END IF;RETURN _user=ANY(public.standby_track_ids(c,_date,'technician')) OR _user=ANY(public.standby_track_ids(c,_date,'supervisor'));END $$;